# Surah Yunus (chapter 10) — part 1: ayat 1-10 (IDs 1365-1374)
SURAH = 10

ENTRIES = {
1365: (
"بسم اللہ الرحمٰن الرحیم — الر — یہ — حکمت والی کتاب — کی آیات ہیں",
"""۱۔ سورہ یونس — حکمت — والی کتاب کی آیات۔
۲۔ ’’الر تِلْكَ آيَاتُ الْكِتَابِ الْحَكِيمِ‘‘ — الر — یہ — حکمت والی کتاب — کی آیات ہیں — یعنی یہ کتاب — حکمت سے — بھری ہوئی ہے۔
۳۔ عملی سبق: قرآن — حکمت کا سمندر ہے؛ باقاعدگی سے تلاوت کرو۔"""
),
1366: (
"کیا — لوگوں کو — تعجب — ہوا — کہ — ہم نے — ان میں سے — ایک مرد پر — وحی کی — کہ — لوگوں کو نصیحت کرو — اور ایمان لانے والوں کو — خوشخبری دو — کہ — ان کے رب کے ہاں — ان کا سچا قدم ہے — کافروں نے کہا — یقیناً یہ — کھلا جادوگر ہے",
"""۱۔ وحی — بشر — پر — تعجب — کی بات نہیں۔
۲۔ ’’أَكَانَ لِلنَّاسِ عَجَبًا أَنْ أَوْحَيْنَا إِلَىٰ رَجُلٍ مِّنْهُمْ أَنْ أَنذِرِ النَّاسَ وَبَشِّرِ الَّذِينَ آمَنُوا أَنَّ لَهُمْ قَدَمَ صِدْقٍ عِندَ رَبِّهِمْ قَالَ الْكَافِرُونَ إِنَّ هَٰذَا لَسَاحِرٌ مُّبِينٌ‘‘ — کیا — لوگوں کو — تعجب — ہوا — کہ — ہم نے — ان میں سے — ایک مرد پر — وحی کی — کہ — لوگوں کو نصیحت کرو — اور ایمان لانے والوں کو — خوشخبری دو — کہ — ان کے رب کے ہاں — ان کا سچا قدم ہے — کافروں نے کہا — یقیناً یہ — کھلا جادوگر ہے — یعنی نبیؐ کی وحی — پر تعجب کرنا — سادہ لوحی ہے؛ کفار — اسے — جادو قرار دیتے ہیں۔
۳۔ عملی سبق: وحی — قائدان سے نہیں — اللہ کی طرف سے ہے؛ ایمان لاؤ۔"""
),
1367: (
"بے شک — تمہارا — وہ — رب ہے — جس نے — آسمان اور زمین — کو — چھ دن میں — بنایا — پھر — عرش پر — استوا کیا — وہ — معاملات — کی تدبیر کرتا ہے — اس کے — بغیر — کسی شفاعت کرنے والے کی — شفاعت — نہیں چلتی — مگر — اس کی اجازت کے بعد — یہ — اللہ — تمہارا — رب ہے — پس — اسی کی — عبادت کرو — کیا — تم — نصیحت نہیں لیتے",
"""۱۔ اللہ — خالق — عرش پر — منتظم۔
۲۔ ’’إِنَّ رَبَّكُمُ اللَّهُ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَىٰ عَلَى الْعَرْشِ يُدَبِّرُ الْأَمْرَ مَا مِن شَفِيعٍ إِلَّا مِن بَعْدِ إِذْنِهِ ذَٰلِكُمُ اللَّهُ رَبُّكُمْ فَاعْبُدُوهُ أَفَلَا تَذَكَّرُونَ‘‘ — بے شک — تمہارا — وہ — رب ہے — جس نے — آسمان اور زمین — کو — چھ دن میں — بنایا — پھر — عرش پر — استوا کیا — وہ — معاملات — کی تدبیر کرتا ہے — اس کے — بغیر — کسی شفاعت کرنے والے کی — شفاعت — نہیں چلتی — مگر — اس کی اجازت کے بعد — یہ — اللہ — تمہارا — رب ہے — پس — اسی کی — عبادت کرو — کیا — تم — نصیحت نہیں لیتے — یعنی اللہ — چھ دن میں آسمان و زمین بنائے — عرش پر استوا کیا — اور سب — معاملات کی تدبیر کرتا ہے؛ شفاعت — صرف — اس کی اجازت سے چلتی ہے۔
۳۔ عملی سبق: عبادت — صرف اللہ کی کرو؛ کسی کی شفاعت — بغیر اجازت — نہیں چلتی۔"""
),
1368: (
"اسی — کی طرف — تم سب — لوٹ کر جاؤ گے — اللہ کا وعدہ — سچا ہے — بے شک وہ — خلقت — کا — آغاز کرتا ہے — پھر — اسے — دوبارہ — پیدا کرے گا — تاکہ — مؤمنوں کو جو — نیک عمل — کرتے ہیں — انصاف سے — بدلہ دے — اور — جنہوں نے — کفر کیا — ان کے لیے — کھولتا پانی کا — شربت — ہے — اور — دردناک عذاب — اس — لیے کہ — وہ کفر کرتے تھے",
"""۱۔ اللہ — خلقت کا آغاز — اور دوبارہ زندگی — کا — مالک ہے۔
۲۔ ’’إِلَيْهِ مَرْجِعُكُمْ جَمِيعًا وَعْدَ اللَّهِ حَقًّا إِنَّهُ يَبْدَأُ الْخَلْقَ ثُمَّ يُعِيدُهُ لِيَجْزِيَ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ بِالْقِسْطِ وَالَّذِينَ كَفَرُوا لَهُمْ شَرَابٌ مِّنْ حَمِيمٍ وَعَذَابٌ أَلِيمٌ بِمَا كَانُوا يَكْفُرُونَ‘‘ — اسی — کی طرف — تم سب — لوٹ کر جاؤ گے — اللہ کا وعدہ — سچا ہے — بے شک وہ — خلقت — کا — آغاز کرتا ہے — پھر — اسے — دوبارہ — پیدا کرے گا — تاکہ — مؤمنوں کو جو — نیک عمل — کرتے ہیں — انصاف سے — بدلہ دے — اور — جنہوں نے — کفر کیا — ان کے لیے — کھولتا پانی کا — شربت — ہے — اور — دردناک عذاب — اس — لیے کہ — وہ کفر کرتے تھے — یعنی آخرت میں — سب — اللہ کے حضور — حاضر ہوں گے؛ مؤمن — نیک عملوں کا بدلہ — پائیں گے؛ کافر — کھولتے پانی اور دردناک عذاب پائیں گے۔
۳۔ عملی سبق: قیامت — سچی ہے؛ زندگی گزارو — سمجھو کہ آگے کا سفر ہے۔"""
),
1369: (
"وہ — وہی — ہے — جس نے — سورج کو — روشن بنایا — اور — چاند کو — نور — اور — اس کے — منزلوں کا — حساب — تجویز کیا — تاکہ — تم — سالوں اور حساب — کی — تعداد — جان سکو — اللہ — نے — یہ — حق کے ساتھ — بنایا — وہ — آیات — کی — تفصیل — بتاتا ہے — علم رکھنے والی قوم — کے لیے",
"""۱۔ سورج — روشنی — چاند — نور — دونوں — اللہ کی نشانیاں۔
۲۔ ’’هُوَ الَّذِي جَعَلَ الشَّمْسَ ضِيَاءً وَالْقَمَرَ نُورًا وَقَدَّرَهُ مَنَازِلَ لِتَعْلَمُوا عَدَدَ السِّنِينَ وَالْحِسَابَ مَا خَلَقَ اللَّهُ ذَٰلِكَ إِلَّا بِالْحَقِّ يُفَصِّلُ الْآيَاتِ لِقَوْمٍ يَعْلَمُونَ‘‘ — وہ — وہی — ہے — جس نے — سورج کو — روشن بنایا — اور — چاند کو — نور — اور — اس کے — منزلوں کا — حساب — تجویز کیا — تاکہ — تم — سالوں اور حساب — کی — تعداد — جان سکو — اللہ — نے — یہ — حق کے ساتھ — بنایا — وہ — آیات — کی — تفصیل — بتاتا ہے — علم رکھنے والی قوم — کے لیے — یعنی سورج — روشن — چاند — نور کا خالق — اللہ ہے؛ منازلِ قمر — سے — سال اور حساب کا علم ہوتا ہے؛ یہ — حق — ہے۔
۳۔ عملی سبق: کائنات — اللہ کی آیات ہیں؛ غور کرو — علم حاصل کرو۔"""
),
1370: (
"بے شک — رات اور دن کے — بدلنے میں — اور — ان — چیزوں میں جنہیں — اللہ — نے — آسمانوں اور زمین میں — بنایا — نشانیاں ہیں — متقی — لوگوں — کے لیے",
"""۱۔ رات اور دن کا بدلنا — اللہ کی نشانی ہے۔
۲۔ ’’إِنَّ فِي اخْتِلَافِ اللَّيْلِ وَالنَّهَارِ وَمَا خَلَقَ اللَّهُ فِي السَّمَاوَاتِ وَالْأَرْضِ لَآيَاتٍ لِّقَوْمٍ يَتَّقُونَ‘‘ — بے شک — رات اور دن کے — بدلنے میں — اور — ان — چیزوں میں جنہیں — اللہ — نے — آسمانوں اور زمین میں — بنایا — نشانیاں ہیں — متقی — لوگوں — کے لیے — یعنی رات و دن کا بدلنا — اور — آسمان و زمین میں — سب کچھ — متقیوں کے لیے — نشانیاں — ہیں۔
۳۔ عملی سبق: متقی — ہر چیز میں اللہ کی قدرت — دیکھتے ہیں۔"""
),
1371: (
"بے شک — وہ لوگ — جو — ہمارے — پیش آنے — کی — امید نہیں رکھتے — اور — دنیا کی زندگی — سے خوش ہو گئے — اور اس میں — چین پایا — اور — وہ — لوگ — ہماری آیات — سے — غفلت میں رہتے ہیں",
"""۱۔ ان لوگوں کا انجام — جنہیں — آخرت کی امید نہیں اور — دنیا میں چین ہے۔
۲۔ ’’إِنَّ الَّذِينَ لَا يَرْجُونَ لِقَاءَنَا وَرَضُوا بِالْحَيَاۃِ الدُّنْيَا وَاطْمَأَنُّوا بِهَا وَالَّذِينَ هُمْ عَنْ آيَاتِنَا غَافِلُونَ‘‘ — بے شک — وہ لوگ — جو — ہمارے — پیش آنے — کی — امید نہیں رکھتے — اور — دنیا کی زندگی — سے خوش ہو گئے — اور اس میں — چین پایا — اور — وہ — لوگ — ہماری آیات — سے — غفلت میں رہتے ہیں — یعنی وہ لوگ — جو آخرت کے ملاقات — کی امید نہیں رکھتے — دنیا کی زندگی — میں چین پا لیتے ہیں — ہماری آیات — سے — غافل — ہیں۔
۳۔ عملی سبق: آخرت — کی امید — کے بغیر زندگی — خالی ہے۔"""
),
1372: (
"یہی لوگ — ان کا ٹھکانا — آگ ہے — ان کے — کیے کا بدلہ",
"""۱۔ غافلوں کا ٹھکانا — جہنم۔
۲۔ ’’أُولَٰئِكَ مَأْوَاهُمُ النَّارُ بِمَا كَانُوا يَكْسِبُونَ‘‘ — یہی لوگ — ان کا ٹھکانا — آگ ہے — ان کے — کیے کا بدلہ — یعنی غافلوں اور دنیا پرستوں کا ٹھکانا — جہنم ہے — ان کے اعمال کی وجہ سے۔
۳۔ عملی سبق: غفلت — جہنم — کا — راستہ ہے؛ بیدار — ہو کر رہو۔"""
),
1373: (
"بے شک — وہ لوگ — جو — ایمان لائے — اور — نیک عمل — کرتے ہیں — انہیں — ان کا — رب — ان — کے ایمان کی وجہ سے — ہدایت دیتا ہے — ان — کے — نیچے — نہریں بہتی ہیں — نعت والی جنتوں میں",
"""۱۔ ایمان اور نیک عمل — جنت — اور نعمتوں — کا — پھل۔
۲۔ ’’إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ يَهْدِيهِمْ رَبُّهُم بِإِيمَانِهِمْ تَجْرِي مِن تَحْتِهِمُ الْأَنْهَارُ فِي جَنَّاتِ النَّعِيمِ‘‘ — بے شک — وہ لوگ — جو — ایمان لائے — اور — نیک عمل — کرتے ہیں — انہیں — ان کا — رب — ان — کے ایمان کی وجہ سے — ہدایت دیتا ہے — ان — کے — نیچے — نہریں بہتی ہیں — نعت والی جنتوں میں — یعنی ایمان اور نیک عمل کرنے والوں — کو — اللہ — ہدایت — دیتا ہے — اور نعمتوں والی جنتوں — میں — نہریں بہتی ہیں۔
۳۔ عملی سبق: ایمان اور عملِ صالح — جنت — تک پہنچاتے ہیں۔"""
),
1374: (
"ان کی — دعا — ان میں — سبحانک اللہم — ہو گی — اور — ان کا — سلام — ان میں — سلام — ہو گا — اور — ان کی — آخری — دعا — الحمد للہ رب العالمین — ہو گی",
"""۱۔ جنت میں — مؤمنوں کی — دعا — سبحانک اللہم — اور — الحمد للہ — ہو گی۔
۲۔ ’’دَعْوَاهُمْ فِيهَا سُبْحَانَكَ اللَّهُمَّ وَتَحِيَّتُهُمْ فِيهَا سَلَامٌ وَآخِرُ دَعْوَاهُمْ أَنِ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ‘‘ — ان کی — دعا — ان میں — سبحانک اللہم — ہو گی — اور — ان کا — سلام — ان میں — سلام — ہو گا — اور — ان کی — آخری — دعا — الحمد للہ رب العالمین — ہو گی — یعنی جنت میں — ان کی دعا — سبحانک اللہم — اور آخری بات — الحمد للہ رب العالمین — ہو گی؛ جنت میں سلام ہو گا۔
۳۔ عملی سبق: اللہ کی حمد — جنت کی زبان ہے؛ دنیا میں بھی — عادی بناؤ۔"""
),
}
